fn verb(m: Method) -> String {
    match m {           // ✗ every variant, but no wildcard
        Get => "read"
        Post => "write"
        Put => "write"
        Delete => "write"
        Patch => "write"
        Head => "read"
        Options => "read"
    }
}

fn verb(m: Method) -> String {
    match m {
        Get => "read"
